arguments.target_content:
itemBuilder: (context, index) {
  final portal = controller.portals[index];
  final isSelected = controller.selectedPortal.value?.id == portal.id;
  return ListTile(
    tileColor: isSelected 
        ? AppTheme.primaryBlue.withValues(alpha: 0.2) 
        : null,
    title: Text(
      portal.name ?? 'N/A',
      style: TextStyle(
        color: AppTheme.textPrimary,
        fontWeight: FontWeight.bold,
      ),
    ),
    subtitle: Text(
      'SL: ${portal.soLuong}',
      style: TextStyle(color: AppTheme.textSecondary),
    ),
    trailing: isSelected
        ? Icon(Icons.check_circle, color: AppTheme.successGreen)
        : null,
    onTap: () => controller.selectPortal(portal),
  );
},

arguments.replacement_content:
itemBuilder: (context, index) {
  final portal = controller.portals[index];
  final isSelected = controller.selectedPortal.value?.id == portal.id;
  return Container(
    margin: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
    decoration: BoxDecoration(
      color: isSelected ? AppTheme.primaryBlue.withValues(alpha: 0.15) : AppTheme.surfaceCard,
      borderRadius: BorderRadius.circular(12),
      border: Border.all(
        color: isSelected ? AppTheme.primaryBlue : AppTheme.dividerColor,
        width: isSelected ? 2 : 1,
      ),
    ),
    child: ListTile(
      contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
      title: Text(
        portal.name ?? 'N/A',
        style: TextStyle(
          color: AppTheme.textPrimary,
          fontWeight: isSelected ? FontWeight.bold : FontWeight.normal,
          fontSize: 16,
        ),
      ),
      subtitle: Text(
        'SL: ${portal.soLuong}',
        style: TextStyle(color: AppTheme.textSecondary, fontSize: 14),
      ),
      trailing: isSelected
          ? Icon(Icons.check_circle_rounded, color: AppTheme.successGreen, size: 28)
          : Icon(Icons.radio_button_unchecked, color: AppTheme.textSecondary, size: 28),
      onTap: () => controller.selectPortal(portal),
    ),
  );
},
